269	// decodeObject strictly decodes one JSON object. Unknown fields, trailing
270	// content and non-object bodies are all rejected.
271	func decodeObject(body []byte, target any) error {
272		if len(bytes.TrimSpace(body)) == 0 {
273			return ValidationError("request body must be a JSON object")
274		}
275		decoder := json.NewDecoder(bytes.NewReader(body))
276		decoder.DisallowUnknownFields()
277		if err := decoder.Decode(target); err != nil {
278			return ValidationError("request body must be a JSON object with known fields: %s", err)
279		}
280		if err := decoder.Decode(new(any)); err != io.EOF {
281			return ValidationError("request body must contain exactly one JSON object")
282		}
283		return nil
284	}
