1	package tracepath
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"sort"
9		"strconv"
10		"strings"
11	)
12	
13	// Server adapts a Service onto net/http. It owns routing, request decoding and
14	// the documented error shape; every rule lives in the service layer.
15	type Server struct {
16		service *Service
17	}
18	
19	// NewServer builds the HTTP handler for one service.
20	func NewServer(service *Service) *Server {
21		return &Server{service: service}
22	}
23	
24	func (s *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
25		status, response, err := s.dispatch(request, splitPath(request.URL.Path))
26		if err != nil {
27			writeError(writer, err)
28			return
29		}
30		writeJSON(writer, status, response)
31	}
32	
33	func (s *Server) dispatch(request *http.Request, parts []string) (int, any, error) {
34		method := request.Method
35		switch {
36		case method == http.MethodGet && len(parts) == 1 && parts[0] == "health":
37			if err := requireQuery(request); err != nil {
38				return 0, nil, err
